## The classic: hash map + doubly linked list

```js
class Node {
  constructor(key, value) {
    this.key = key; this.value = value;
    this.prev = null; this.next = null;
  }
}

class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();

    // Sentinel nodes remove every null check
    this.head = new Node(null, null);   // most recent side
    this.tail = new Node(null, null);   // least recent side
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  #remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  #addFront(node) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }

  get(key) {
    const node = this.map.get(key);
    if (!node) return -1;

    this.#remove(node);
    this.#addFront(node);      // mark as most recently used
    return node.value;
  }

  put(key, value) {
    const existing = this.map.get(key);
    if (existing) this.#remove(existing);

    const node = new Node(key, value);
    this.map.set(key, node);
    this.#addFront(node);

    if (this.map.size > this.capacity) {
      const lru = this.tail.prev;
      this.#remove(lru);
      this.map.delete(lru.key);     // ← needs the key, hence storing it on the node
    }
  }
}
```

