## Valid palindrome II — one deletion allowed

```js
function validPalindrome(s) {
  function check(left, right) {
    while (left < right) {
      if (s[left] !== s[right]) return false;
      left++; right--;
    }
    return true;
  }

  let left = 0, right = s.length - 1;
  while (left < right) {
    if (s[left] !== s[right]) {
      // Try skipping either side — one of them must work
      return check(left + 1, right) || check(left, right - 1);
    }
    left++; right--;
  }
  return true;
}
```

Still **O(n)** — the helper runs at most twice, and each run is bounded by the remaining length. Candidates often assume this is O(n²); it is not.

