## The frontend version

"Top 10 results by score" is this problem. In practice you would sort, because n is small and readability wins — but knowing the heap approach matters when the data streams in and you cannot hold it all.

## Undirected — visited is enough

```js
function traverse(node, visited = new Set()) {
  if (!node || visited.has(node)) return;
  visited.add(node);

  for (const neighbour of node.neighbours) {
    traverse(neighbour, visited);
  }
}
```

Use the object reference itself as the key — a `Set` compares by identity, which is exactly right for graph nodes.

---

## Directed — two sets

```js
function hasCycle(graph) {
  const visited = new Set();       // fully processed
  const inStack = new Set();       // on the CURRENT path

  function dfs(node) {
    if (inStack.has(node)) return true;    // ← back edge = cycle
    if (visited.has(node)) return false;   // already explored, no cycle found

    inStack.add(node);

    for (const next of graph[node] ?? []) {
      if (dfs(next)) return true;
    }

    inStack.delete(node);          // ← leaving this path
    visited.add(node);
    return false;
  }

  return Object.keys(graph).some((node) => dfs(node));
}
```

**Why two sets:** a node reachable by two different paths is not a cycle. A node reachable *from itself* is. `inStack` tracks the current path; removing on the way out is the key line.

---

## Cycle-safe deep clone

The practical version of this problem:

```js
function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') return value;
  if (seen.has(value)) return seen.get(value);      // return the existing clone

  const result = Array.isArray(value) ? [] : {};
  seen.set(value, result);                          // ← register BEFORE recursing

  for (const [key, val] of Object.entries(value)) {
    result[key] = deepClone(val, seen);
  }
  return result;
}
```

Registering the clone before descending is what breaks the cycle — otherwise `obj.self = obj` recurses forever. `WeakMap` lets the graph be garbage collected.

---

## Topological sort — the useful application

Ordering tasks with dependencies, and detecting an impossible cycle at the same time:

```js
function topoSort(graph) {
  const visited = new Set(), inStack = new Set(), order = [];

  function dfs(node) {
    if (inStack.has(node)) throw new Error(`Cycle at ${node}`);
    if (visited.has(node)) return;

    inStack.add(node);
    for (const dep of graph[node] ?? []) dfs(dep);
    inStack.delete(node);

    visited.add(node);
    order.push(node);      // added AFTER dependencies → correct order
  }

  Object.keys(graph).forEach(dfs);
  return order;
}
```

This is exactly what a bundler does to order modules, and what a task runner does for job dependencies. "Circular dependency detected" from webpack is this algorithm firing.

